{"name": "create_inventory_transfer_log", "query": "
-- ============================================================
-- Audit log table for all inventory transfer attempts
-- ============================================================
CREATE TABLE IF NOT EXISTS inventory_transfer_log (
    log_id               SERIAL PRIMARY KEY,
    transfer_timestamp   TIMESTAMP    DEFAULT NOW(),
    source_inventory_id  INTEGER      NOT NULL,
    target_inventory_id  INTEGER      NOT NULL,
    part_num             VARCHAR      NOT NULL,
    color_id             INTEGER      NOT NULL,
    quantity_transferred INTEGER      NOT NULL,
    transfer_reason      VARCHAR      NOT NULL,
    transfer_status      VARCHAR      NOT NULL
        CHECK (transfer_status IN ('success', 'failed')),
    error_message        TEXT
);

-- Indexes for efficient querying of audit history
CREATE INDEX IF NOT EXISTS idx_transfer_log_source
    ON inventory_transfer_log (source_inventory_id);

CREATE INDEX IF NOT EXISTS idx_transfer_log_target
    ON inventory_transfer_log (target_inventory_id);

CREATE INDEX IF NOT EXISTS idx_transfer_log_timestamp
    ON inventory_transfer_log (transfer_timestamp DESC);

CREATE INDEX IF NOT EXISTS idx_transfer_log_status
    ON inventory_transfer_log (transfer_status);

COMMENT ON TABLE inventory_transfer_log IS
    'Audit trail for all inventory part transfer attempts, both successful and failed.';

COMMENT ON COLUMN inventory_transfer_log.log_id               IS 'Unique identifier for each log entry';
COMMENT ON COLUMN inventory_transfer_log.transfer_timestamp   IS 'UTC timestamp when the transfer was attempted';
COMMENT ON COLUMN inventory_transfer_log.source_inventory_id  IS 'Inventory ID parts were moved FROM';
COMMENT ON COLUMN inventory_transfer_log.target_inventory_id  IS 'Inventory ID parts were moved TO';
COMMENT ON COLUMN inventory_transfer_log.part_num             IS 'LEGO part number being transferred';
COMMENT ON COLUMN inventory_transfer_log.color_id             IS 'Color ID of the part being transferred';
COMMENT ON COLUMN inventory_transfer_log.quantity_transferred IS 'Number of parts requested for transfer';
COMMENT ON COLUMN inventory_transfer_log.transfer_reason      IS 'Business reason supplied by the caller';
COMMENT ON COLUMN inventory_transfer_log.transfer_status      IS 'Outcome: ''success'' or ''failed''';
COMMENT ON COLUMN inventory_transfer_log.error_message        IS 'Populated only on failure — contains the validation or runtime error';
"}

