{"name": "recreate_log_helper_with_dblink", "query": "
DROP FUNCTION IF EXISTS log_transfer_attempt(INTEGER, INTEGER, VARCHAR, INTEGER, INTEGER, VARCHAR, VARCHAR, TEXT);

CREATE FUNCTION log_transfer_attempt(
    p_src   INTEGER,
    p_tgt   INTEGER,
    p_part  VARCHAR,
    p_color INTEGER,
    p_qty   INTEGER,
    p_rsn   VARCHAR,
    p_stat  VARCHAR,
    p_err   TEXT DEFAULT NULL
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_conn  TEXT;
    v_sql   TEXT;
BEGIN
    SELECT value INTO v_conn
    FROM   _transfer_config
    WHERE  key = 'audit_conn';

    v_sql := format(
        'INSERT INTO inventory_transfer_log'
        ' (source_inventory_id,target_inventory_id,part_num,color_id,'
        '  quantity_transferred,transfer_reason,transfer_status,error_message)'
        ' VALUES (%s,%s,%L,%s,%s,%L,%L,%L)',
        p_src, p_tgt, p_part, p_color, p_qty, p_rsn, p_stat, p_err
    );

    PERFORM dblink_exec(v_conn, v_sql);
END;
$$;

COMMENT ON FUNCTION log_transfer_attempt IS
'Writes one audit row to inventory_transfer_log via dblink (autonomous
transaction).  Called by transfer_parts() for both success and failure paths.
Uses connection string from _transfer_config.audit_conn.';
"}

